import sys
import numpy as np
from PIL import Image

img = Image.open('input_files/input-01.png').convert('RGB')
a = np.array(img).astype(int)
r, g, b = a[:,:,0], a[:,:,1], a[:,:,2]
mask = (r+g+b) < 600

def segs_1d(arr, minlen):
    out=[]; i=0; n=len(arr)
    while i<n:
        if arr[i]:
            j=i
            while j<n and arr[j]: j+=1
            if j-i>=minlen: out.append((i,j-1))
            i=j
        else: i+=1
    return out

def vseg(x0,y0,x1,y1,minlen=15, band=1):
    """vertical line segments: for each column, find y-segments"""
    res=[]
    for x in range(x0,x1):
        col = mask[y0:y1, max(0,x-band):x+band+1].any(axis=1)
        for (s,e) in segs_1d(col, minlen):
            res.append((x, y0+s, y0+e))
    # merge segments across adjacent columns
    res.sort(key=lambda t:(t[0]))
    merged=[]
    for (x,s,e) in res:
        found=False
        for m in merged:
            if abs(x-m[0])<=2 and not (e < m[1]-3 or s > m[2]+3):
                # overlap in y
                os_, oe = max(s,m[1]), min(e,m[2])
                if oe-os_ >= 0:
                    m[0]=(m[0]*m[3]+x)/(m[3]+1); m[1]=min(m[1],s); m[2]=max(m[2],e); m[3]+=1
                    found=True; break
        if not found:
            merged.append([float(x),s,e,1])
    return merged

def hseg(x0,y0,x1,y1,minlen=15, band=1):
    res=[]
    for y in range(y0,y1):
        row = mask[max(0,y-band):y+band+1, x0:x1].any(axis=0)
        for (s,e) in segs_1d(row, minlen):
            res.append((y, x0+s, x0+e))
    res.sort(key=lambda t:(t[0]))
    merged=[]
    for (y,s,e) in res:
        found=False
        for m in merged:
            if abs(y-m[0])<=2:
                os_, oe = max(s,m[1]), min(e,m[2])
                if oe-os_ >= 0:
                    m[0]=(m[0]*m[3]+y)/(m[3]+1); m[1]=min(m[1],s); m[2]=max(m[2],e); m[3]+=1
                    found=True; break
        if not found:
            merged.append([float(y),s,e,1])
    return merged

if __name__ == '__main__':
    mode = sys.argv[1]
    x0,y0,x1,y1 = map(int, sys.argv[2:6])
    minlen = int(sys.argv[6]) if len(sys.argv)>6 else 15
    if mode=='v':
        for m in sorted(vseg(x0,y0,x1,y1,minlen), key=lambda m:-(m[2]-m[1])):
            print(f"x={m[0]:7.1f}  y: {m[1]:4d} - {m[2]:4d}  len={m[2]-m[1]+1}")
    else:
        for m in sorted(hseg(x0,y0,x1,y1,minlen), key=lambda m:-(m[2]-m[1])):
            print(f"y={m[0]:7.1f}  x: {m[1]:4d} - {m[2]:4d}  len={m[2]-m[1]+1}")

